import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { HomeIcon, ShoppingBagIcon } from '@heroicons/react/24/outline';

const Sidebar = () => {
  const location = useLocation();

  const menuItems = [
    { path: '/', label: 'Dashboard' },
    { path: '/store1', label: 'Store 1' },
    { 
      path: '/store2', 
      label: 'Store 2',
      subItems: [
        { path: '/store2/stock', label: 'Stok İşlemleri' },
        { path: '/store2/sales', label: 'Satış İşlemleri' },
        { path: '/store2/returns', label: 'İade İşlemleri' }
      ]
    },
    { 
      path: '/store3', 
      label: 'Store 3',
      subItems: [
        { path: '/store3/stock', label: 'Stok İşlemleri' },
        { path: '/store3/sales', label: 'Satış İşlemleri' },
        { path: '/store3/returns', label: 'İade İşlemleri' }
      ]
    }
  ];

  return (
    <div className="flex flex-col w-64 bg-gray-800 h-screen fixed">
      <div className="flex items-center justify-center h-16 bg-gray-900">
        <span className="text-white text-xl font-semibold">MultiStore</span>
      </div>
      <nav className="mt-5 flex-1">
        <div className="px-2 space-y-1">
          {menuItems.map((item) => (
            <div key={item.path} className="mb-2">
              {item.subItems ? (
                <>
                  <div
                    className={`${
                      location.pathname.startsWith(item.path)
                        ? 'bg-gray-900 text-white'
                        : 'text-gray-300 hover:bg-gray-700 hover:text-white'
                    } group flex items-center px-2 py-2 text-base font-medium rounded-md cursor-pointer`}
                  >
                    {item.label}
                  </div>
                  <ul className="ml-4 mt-2 space-y-2">
                    {item.subItems.map((subItem) => (
                      <li key={subItem.path}>
                        <Link
                          to={subItem.path}
                          className={`${
                            location.pathname === subItem.path
                              ? 'bg-gray-900 text-white'
                              : 'text-gray-300 hover:bg-gray-700 hover:text-white'
                          } group flex items-center px-2 py-2 text-sm font-medium rounded-md`}
                        >
                          {subItem.label}
                        </Link>
                      </li>
                    ))}
                  </ul>
                </>
              ) : (
                <Link
                  to={item.path}
                  className={`${
                    location.pathname === item.path
                      ? 'bg-gray-900 text-white'
                      : 'text-gray-300 hover:bg-gray-700 hover:text-white'
                  } group flex items-center px-2 py-2 text-base font-medium rounded-md`}
                >
                  {item.label}
                </Link>
              )}
            </div>
          ))}
        </div>
      </nav>
    </div>
  );
};

export default Sidebar;
